#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *storage;
    size_t capacity;
    size_t head; /* write position */
    size_t tail; /* read position */
    size_t sz;   /* current bytes stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->storage = calloc(capacity, sizeof(uint8_t));
    if (!rb->storage) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->sz = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->storage);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t n, avail;

    if (!rb || !data || len == 0)
        return 0;

    avail = rb->capacity - rb->sz;
    if (len > avail)
        n = avail;
    else
        n = len;

    /* First segment: from head to end of storage */
    size_t first = rb->capacity - rb->head;

    if (n <= first) {
        memcpy(rb->storage + rb->head, data, n);
        rb->head = (rb->head + n) % rb->capacity;
    } else {
        memcpy(rb->storage + rb->head, data, first);
        memcpy(rb->storage, data + first, n - first);
        rb->head = n - first;
    }

    rb->sz += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t n;

    if (!rb || !out || len == 0)
        return 0;

    if (len > rb->sz)
        n = rb->sz;
    else
        n = len;

    /* First segment: from tail to end of storage */
    size_t first = rb->capacity - rb->tail;

    if (n <= first) {
        memcpy(out, rb->storage + rb->tail, n);
        rb->tail = (rb->tail + n) % rb->capacity;
    } else {
        memcpy(out, rb->storage + rb->tail, first);
        memcpy(out + first, rb->storage, n - first);
        rb->tail = n - first;
    }

    rb->sz -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t n;

    if (!rb || !out || len == 0)
        return 0;

    if (len > rb->sz)
        n = rb->sz;
    else
        n = len;

    /* Copy from tail without advancing */
    size_t first = rb->capacity - rb->tail;

    if (n <= first) {
        memcpy(out, rb->storage + rb->tail, n);
    } else {
        memcpy(out, rb->storage + rb->tail, first);
        memcpy(out + first, rb->storage, n - first);
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->sz;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->sz = 0;
}

#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include "ringbuf.h"

static int passed = 0, failed = 0;

#define TEST(cond) do { \
    if (cond) { passed++; } \
    else { failed++; printf("FAIL: %s at line %d\n", #cond, __LINE__); } \
} while (0)

int main(void)
{
    ringbuf_t *rb;
    uint8_t buf[16];
    size_t n;

    /* NULL safety */
    TEST(rb_create(0) == NULL);
    TEST(rb_create(1) != NULL);
    rb_destroy(NULL);

    rb = rb_create(4);
    TEST(rb != NULL);
    TEST(rb_capacity(rb) == 4);
    TEST(rb_size(rb) == 0);
    TEST(rb_read(rb, buf, 16) == 0);
    TEST(rb_peek(rb, buf, 16) == 0);

    /* Write fits */
    uint8_t w[4] = {1, 2, 3, 4};
    n = rb_write(rb, w, 4);
    TEST(n == 4);
    TEST(rb_size(rb) == 4);

    /* Peek */
    n = rb_peek(rb, buf, 8);
    TEST(n == 4);
    TEST(memcmp(buf, w, 4) == 0);

    /* Read all back */
    memset(buf, 0, sizeof(buf));
    n = rb_read(rb, buf, 16);
    TEST(n == 4);
    TEST(memcmp(buf, w, 4) == 0);
    TEST(rb_size(rb) == 0);

    /* Write more than fits (partial write) */
    uint8_t big[8] = {10, 11, 12, 13, 14, 15, 16, 17};
    n = rb_write(rb, big, 8);
    TEST(n == 4); /* only 4 fits */

    uint8_t exp[4] = {9, 10, 11, 12};
    for (int i = 0; i < 4; i++)
        expected[i] = big[i];  /* wrap-around order */

    TEST(rb_size(rb) == 4);
    n = rb_read(rb, buf, 8);
    TEST(n == 4);

    /* Verify wrap-around content: writes {10,11,12,13} should fill buffer,
       but we got only {10,11,12,13,...} first 4 written. Read order is oldest first */
    uint8_t want[4] = {10, 11, 12, 13};
    TEST(memcmp(buf, want, 4) == 0);

    /* Clear */
    rb_clear(rb);
    TEST(rb_size(rb) == 0);
    TEST(rb_capacity(rb) == 4);

    /* Large write into cleared buffer */
    uint8_t w2[4] = {99, 100, 101, 102};
    n = rb_write(rb, w2, 4);
    TEST(n == 4);

    /* Write then read multiple times to stress wrap-around */
    for (int i = 0; i < 3; i++) {
        uint8_t b[6] = {0};
        memset(buf, 0, sizeof(buf));
        n = rb_read(rb, buf, 2);
        TEST(n == 4 - i * 0); /* size drops */
        if (i < 3)
            TEST(rb_size(rb) == 4 - 1 - i); /* after read of 4: 4-i*1... let me recalc */
    }

    rb_destroy(rb);
    rb_destroy(NULL);

    printf("%d passed, %d failed\n", passed, failed);
    return failed > 0 ? 1 : 0;
}

#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include "ringbuf.h"

static int passed = 0, failed = 0;

#define TEST(cond) do { \
    if (cond) { passed++; } \
    else { failed++; printf("FAIL: %s at line %d\n", #cond, __LINE__); } \
} while (0)

int main(void)
{
    ringbuf_t *rb;
    uint8_t buf[16];
    size_t n;

    /* NULL safety */
    TEST(rb_create(0) == NULL);
    rb_destroy(NULL);
    rb_read(NULL, buf, 1) == 0;
    rb_write(NULL, buf, 1) == 0;
    rb_peek(NULL, buf, 1) == 0;

    rb = rb_create(4);
    TEST(rb != NULL);
    TEST(rb_capacity(rb) == 4);
    TEST(rb_size(rb) == 0);

    /* Write fits */
    uint8_t w[4] = {1, 2, 3, 4};
    n = rb_write(rb, w, 4);
    TEST(n == 4);
    TEST(rb_size(rb) == 4);

    /* Peek (doesn't remove bytes) */
    n = rb_peek(rb, buf, 8);
    TEST(n == 4);
    TEST(memcmp(buf, w, 4) == 0);
    TEST(rb_size(rb) == 4); /* unchanged */

    /* Read all */
    memset(buf, 0, sizeof(buf));
    n = rb_read(rb, buf, 16);
    TEST(n == 4);
    TEST(memcmp(buf, w, 4) == 0);
    TEST(rb_size(rb) == 0);

    /* Partial write (write more than fits) */
    uint8_t big[8] = {10, 11, 12, 13, 14, 15, 16, 17};
    n = rb_write(rb, big, 8);
    TEST(n == 4);
    TEST(rb_size(rb) == 4);

    /* Verify: written bytes are the first 4 of big */
    uint8_t want[4] = {10, 11, 12, 13};
    n = rb_read(rb, buf, 8);
    TEST(n == 4);
    TEST(memcmp(buf, want, 4) == 0);

    /* Write 1, read 1, write fill to trigger wrap-around */
    rb_clear(rb);
    uint8_t a1[1] = {42};
    n = rb_write(rb, a1, 1);
    TEST(n == 1);
    TEST(rb_size(rb) == 1);

    /* Now write 3 more: should wrap around */
    uint8_t blk[3] = {99, 100, 101};
    n = rb_write(rb, blk, 3);
    TEST(n == 3);
    TEST(rb_size(rb) == 4);

    /* Read all and verify order: 42, 99, 100, 101 */
    uint8_t want2[4] = {42, 99, 100, 101};
    n = rb_read(rb, buf, 4);
    TEST(n == 4);
    TEST(memcmp(buf, want2, 4) == 0);

    /* Write 2, clear, write 3 (overwrites old head position) */
    rb_clear(rb);
    uint8_t c1[4] = {1, 2, 3, 4};
    n = rb_write(rb, c1, 4);
    TEST(n == 4);

    uint8_t rbuf[2];
    n = rb_read(rb, rbuf, 2);
    TEST(n == 2);
    TEST(rbuf[0] == 1 && rbuf[1] == 2);
    TEST(rb_size(rb) == 2);

    rb_clear(rb);
    uint8_t c2[3] = {5, 6, 7};
    n = rb_write(rb, c2, 3);
    TEST(n == 3);
    n = rb_read(rb, buf, 4);
    TEST(n == 3);
    TEST(buf[0]==5 && buf[1]==6 && buf[2]==7);

    printf("%d passed, %d failed\n", passed, failed);
    rb_destroy(rb);
    return failed > 0 ? 1 : 0;
}

